$http.SetCookie as $cookie
$cookie(* as $param);

$param #{
    until: "*.HttpOnly"
}-> as $sink

$sink.HttpOnly?{have: false} as $false
$sink.HttpOnly?{have: true} as $true

$true -->?{have: SetCookie}<getCallee> as $safe

